/* ===================== BÀI 6 · FLAGS và ý nghĩa phép toán ===================== */
/* Bài 6 · FLAGS và ý nghĩa phép toán (AMTS-EMB-002-M02-L02, X86-006) — sinh bởi tools/author/mpu8086/l06.py, không sửa tay.
   Ví dụ cho trình mô phỏng 8086 và bài tập chấm tự động (đề, code mẫu, test). Lời giải không nằm ở đây. */
const P6=[{"label": "Ví dụ: một phép cộng, sáu cờ", "code": "; Ví dụ 1: một phép cộng, sáu cờ trạng thái\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nco      DW      ?                       ; FLAGS sau phép cộng\nkq      DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, 7FH                 ; +127: số dương 8 bit lớn nhất\n        ADD     AL, 1                   ; AL = 80h\n        MOV     kq, AL                  ; MOV không đổi cờ\n        PUSHF                           ; cất FLAGS vào ngăn xếp\n        POP     co                      ; lấy ra, ghi vào biến co\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bấm Từng bước tới ADD AL, 1 và nhìn chín cờ ở phần Thanh ghi: OF, SF, AF thành 1; CF, ZF, PF bằng 0. MOV kq, AL không đổi cờ nào. PUSHF / POP co chép FLAGS vào biến co: FA92h = F202h + OF 0800h + SF 0080h + AF 0010h. Đoán trước: sau ADD, AL bằng bao nhiêu (hệ 16)? Đáp án 80h."}, {"label": "Ví dụ: cùng mẫu bit, hai cách đọc", "code": "; Ví dụ 2: cùng mẫu bit, hai cách đọc\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nco1     DW      ?\nco2     DW      ?\nkq1     DB      ?\nkq2     DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, 0F0H                ; không dấu 240, có dấu -16\n        ADD     AL, 20H                 ; + 32: AL = 10h\n        MOV     kq1, AL\n        PUSHF\n        POP     co1                     ; CF = 1, OF = 0\n        MOV     AL, 70H                 ; không dấu 112, có dấu +112\n        ADD     AL, 20H                 ; + 32: AL = 90h\n        MOV     kq2, AL\n        PUSHF\n        POP     co2                     ; CF = 0, OF = 1\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Hai phép cộng dòng 2 và 3 của bảng ở mục 6.2. F0h + 20h: hiểu không dấu là tràn (CF = 1), hiểu có dấu −16 + 32 = 16 đúng (OF = 0): co1 = F203h. 70h + 20h: không dấu đúng (CF = 0), có dấu 112 + 32 vượt 127 (OF = 1): co2 = FA86h (thêm PF vì 90h có 2 bit 1). Đoán trước: sau ADD AL, 20h lần đầu, AL bằng bao nhiêu? Đáp án 10h."}, {"label": "Ví dụ: phép trừ, CF là cờ mượn", "code": "; Ví dụ 3: phép trừ, CF là cờ mượn\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nco1     DW      ?\nco2     DW      ?\nkq1     DB      ?\nkq2     DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, 05H\n        SUB     AL, 07H                 ; 5 - 7: AL = FEh (-2)\n        MOV     kq1, AL\n        PUSHF\n        POP     co1                     ; CF = 1: phải mượn\n        MOV     AL, 80H                 ; có dấu -128\n        SUB     AL, 01H                 ; AL = 7Fh (+127)\n        MOV     kq2, AL\n        PUSHF\n        POP     co2                     ; OF = 1: -128 - 1 tràn có dấu\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Với SUB, CF = 1 nghĩa là phải mượn: 5 − 7 cho FEh và CF = 1, SF = 1, AF = 1 (co1 = F293h). 80h − 01h: không dấu 128 − 1 = 127 đúng (CF = 0) nhưng có dấu −128 − 1 tràn (OF = 1): co2 = FA12h. Đoán trước: sau SUB AL, 07h, AL bằng bao nhiêu? Đáp án FEh."}, {"label": "Bẫy: INC không đổi cờ CF", "code": "; Bẫy: INC không đổi cờ CF\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nco1     DW      ?                       ; sau ADD AL, 1\nco2     DW      ?                       ; sau INC AL\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, 0FFH\n        ADD     AL, 1                   ; AL = 00h, CF = 1\n        PUSHF\n        POP     co1\n        CLC                             ; xóa CF\n        MOV     AL, 0FFH\n        INC     AL                      ; AL = 00h, ZF = 1, CF vẫn 0\n        PUSHF\n        POP     co2\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy cố ý: ADD AL, 1 với AL = FFh cho CF = 1 (co1 = F257h). Sau CLC, INC AL với AL = FFh cũng cho AL = 00h và ZF = 1 nhưng CF vẫn 0 (co2 = F256h): INC không đổi CF. Xem cờ CF ở phần Thanh ghi không đổi màu sau INC AL. Đoán trước: sau INC AL, AL bằng bao nhiêu? Đáp án 00h."}, {"label": "Bẫy: MOV không đổi cờ", "code": "; Bẫy: MOV không đổi cờ\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nco      DW      ?\nkq      DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AL, 5\n        SUB     AL, 5                   ; AL = 0: ZF = 1\n        MOV     AL, 9                   ; AL = 9 nhưng ZF vẫn là 1\n        MOV     kq, AL\n        PUSHF\n        POP     co                      ; ZF của phép SUB, không phải của AL\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Bẫy cố ý: SUB AL, 5 cho 0 nên ZF = 1. MOV AL, 9 đổi AL nhưng không đổi cờ, nên khi PUSHF, ZF vẫn là 1 dù AL = 9 (co = F246h). Cờ mô tả phép tính cuối cùng có đặt cờ, không mô tả giá trị đang có trong thanh ghi. Đoán trước: sau MOV AL, 9, AL bằng bao nhiêu? Đáp án 09h."}, {"label": "Ví dụ: PF chỉ xét 8 bit thấp, AF nhìn bit 3", "code": "; Ví dụ 6: PF chỉ xét 8 bit thấp, AF nhìn bit 3\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nco      DW      ?\nkq      DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, 0108H\n        MOV     BX, 0008H\n        ADD     AX, BX                  ; AX = 0110h\n        MOV     kq, AX\n        PUSHF\n        POP     co                      ; PF xét 10h (một bit 1), AF = 1\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "ADD AX, BX 16 bit: 0108h + 0008h = 0110h. PF chỉ xét byte thấp 10h (một bit 1, lẻ) nên PF = 0; AF = 1 vì 8 + 8 nhớ qua bit 3. co = F212h. Đoán trước: sau ADD AX, BX, AX bằng bao nhiêu? Đáp án 0110h."}, {"label": "Lỗi: cộng từng byte mà quên số nhớ", "code": "; Lỗi: cộng từng byte mà quên số nhớ\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nsai     DW      ?                       ; mong đợi 1300h\ndung    DW      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AX, 12FFH\n        MOV     BX, 0001H\n        ADD     AL, BL                  ; FFh + 01h = 00h, CF = 1\n        ADD     AH, BH                  ; 12h + 00h: số nhớ bị bỏ quên\n        MOV     sai, AX                 ; 1200h\n        MOV     AX, 12FFH\n        ADD     AL, BL\n        ADC     AH, BH                  ; cộng thêm CF: 12h + 00h + 1\n        MOV     dung, AX                ; 1300h\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "input": "", "note": "Lỗi logic cố ý: cộng 12FFh + 0001h bằng hai lệnh ADD 8 bit. ADD AL, BL cho 00h và CF = 1, nhưng ADD AH, BH bỏ qua CF nên sai = 1200h. Bản sửa ngay bên dưới dùng ADC AH, BH cộng thêm CF: dung = 1300h. Đoán trước: sau ADC AH, BH, AH bằng bao nhiêu? Đáp án 13h."}];
const sim6=makeX86Sim(document.getElementById("x86-l6"),{id:"s6",presets:P6,file:"BAI6.ASM"});
makeX86Ex(document.getElementById("ex-l6"),sim6,[{"t": "Cờ của phép cộng", "d": "Đọc hai phím a, b bằng INT 21h hàm 08h. Tính a + b trên 8 bit (a, b là mã ASCII). Ghi kết quả vào biến tong (1 byte) và ghi cả thanh ghi FLAGS ngay sau phép cộng vào biến co (1 word) bằng PUSHF rồi POP co (trang chấm so sáu cờ trạng thái CF, PF, AF, ZF, SF, OF của co). Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 1: tong = a + b, co = FLAGS sau phép cộng\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nco      DW      ?                       ; giữ nguyên tên biến\ntong    DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H                     ; AL = a\n        MOV     BL, AL\n        MOV     AH, 08H\n        INT     21H                     ; AL = b\n; Viết code ở đây: cộng, ghi tong và co\n\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "AB", "mem": [{"at": "tong", "bytes": [131]}, {"at": "co", "word": 64130, "mask": 2261}]}, {"in": "  ", "mem": [{"at": "tong", "bytes": [64]}, {"at": "co", "word": 61954, "mask": 2261}]}, {"in": "pP", "mem": [{"at": "tong", "bytes": [192]}, {"at": "co", "word": 64134, "mask": 2261}]}, {"in": "05", "mem": [{"at": "tong", "bytes": [101]}, {"at": "co", "word": 61958, "mask": 2261}]}, {"in": "99", "mem": [{"at": "tong", "bytes": [114]}, {"at": "co", "word": 61974, "mask": 2261}]}, {"in": "~~", "mem": [{"at": "tong", "bytes": [252]}, {"at": "co", "word": 64150, "mask": 2261}]}]}, {"t": "Trừ 16 bit và cờ mượn", "d": "Đọc 4 phím k1, k2, k3, k4 bằng INT 21h hàm 08h; x = k1k2 (k1 là byte cao), y = k3k4. Ghi hieu = x − y (16 bit, bỏ số mượn) và muon = 1 nếu phép trừ không dấu phải mượn (x < y), ngược lại muon = 0. Code mẫu đã tính hieu. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 2: hieu = x - y (16 bit), muon = CF\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\nhieu    DW      ?                       ; giữ nguyên tên biến\nmuon    DB      ?\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     AH, 08H\n        INT     21H\n        MOV     BH, AL                  ; x = k1k2 trong BX\n        MOV     AH, 08H\n        INT     21H\n        MOV     BL, AL\n        MOV     AH, 08H\n        INT     21H\n        MOV     CH, AL                  ; y = k3k4 trong CX\n        MOV     AH, 08H\n        INT     21H\n        MOV     CL, AL\n        SUB     BX, CX\n        MOV     hieu, BX\n        MOV     muon, 0\n; Viết code ở đây: muon = 1 nếu phép trừ phải mượn\n\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "BAAB", "mem": [{"at": "hieu", "word": 255}, {"at": "muon", "bytes": [0]}]}, {"in": "ABBA", "mem": [{"at": "hieu", "word": 65281}, {"at": "muon", "bytes": [1]}]}, {"in": "ABAB", "mem": [{"at": "hieu", "word": 0}, {"at": "muon", "bytes": [0]}]}, {"in": "~~  ", "mem": [{"at": "hieu", "word": 24158}, {"at": "muon", "bytes": [0]}]}, {"in": "  ~~", "mem": [{"at": "hieu", "word": 41378}, {"at": "muon", "bytes": [1]}]}, {"in": "A0A1", "mem": [{"at": "hieu", "word": 65535}, {"at": "muon", "bytes": [1]}]}]}, {"t": "Tổng 5 phím nhanh hơn", "d": "Đọc 5 phím bằng INT 21h hàm 08h và ghi tổng mã ASCII của chúng (16 bit) vào biến tong. Code mẫu đã đúng nhưng cộng thẳng vào ô nhớ và còn so sánh thừa CMP CX, 0 sau DEC CX. Viết lại để đạt cả giới hạn chu kỳ và giới hạn số byte mã. Không in gì; kết thúc bằng INT 21h hàm 4Ch.", "start": "; Bài tập 3: tổng 16 bit mã ASCII của 5 phím\n; Bản này đúng nhưng cộng thẳng vào ô nhớ và\n; so sánh thừa. Hãy viết lại.\n        .MODEL  SMALL\n        .STACK  100H\n        .DATA\ntong    DW      ?                       ; giữ nguyên tên biến\n        .CODE\nMAIN    PROC\n        MOV     AX, @DATA\n        MOV     DS, AX\n        MOV     tong, 0\n        MOV     CX, 5\ndoc:\n        MOV     AH, 08H\n        INT     21H\n        MOV     AH, 0                   ; AX = mã phím (16 bit)\n        ADD     tong, AX                ; cộng vào ô nhớ\n        DEC     CX\n        CMP     CX, 0                   ; so sánh lại với 0\n        JNZ     doc\n        MOV     AX, 4C00H\n        INT     21H\nMAIN    ENDP\n        END     MAIN\n", "tests": [{"in": "ABCDE", "mem": [{"at": "tong", "word": 335}]}, {"in": "     ", "mem": [{"at": "tong", "word": 160}]}, {"in": "~~~~~", "mem": [{"at": "tong", "word": 630}]}, {"in": "00000", "mem": [{"at": "tong", "word": 240}]}, {"in": "zzzzz", "mem": [{"at": "tong", "word": 610}]}, {"in": "Hello", "mem": [{"at": "tong", "word": 500}]}], "perf": {"cycles": 480, "bytes": 32}}]);

makeQuiz("quiz6","score6",[{"q": "Sau ba lệnh sau, AL, CF, OF bằng bao nhiêu?<pre class=\"mp-asm\">        MOV     AL, 90H\n        MOV     BL, 90H\n        ADD     AL, BL<\/pre>", "o": ["AL = 20h, CF = 1, OF = 1", "AL = 20h, CF = 1, OF = 0", "AL = 20h, CF = 0, OF = 1", "AL = 00h, CF = 1, OF = 1"], "a": 0, "e": "Không dấu: 144 + 144 = 288 = 120h, AL giữ 20h và CF = 1. Có dấu: (−112) + (−112) = −224 nằm ngoài −128…127 nên OF = 1 (hai số âm cộng ra số dương 20h)."}, {"q": "Sau đoạn sau, AL, ZF, CF bằng bao nhiêu?<pre class=\"mp-asm\">        STC\n        MOV     AL, 0FFH\n        INC     AL<\/pre>", "o": ["AL = 00h, ZF = 1, CF = 0 (INC xóa CF)", "AL = 00h, ZF = 1, CF = 1 (CF giữ từ STC)", "AL = 00h, ZF = 0, CF = 1 (ZF chỉ đổi khi CMP)", "AL = 01h, ZF = 0, CF = 1 (INC cộng thêm CF)"], "a": 1, "e": "INC tính FFh + 1 = 00h nên ZF = 1, nhưng INC không đổi CF: CF vẫn là 1 do STC đặt. Nhầm phổ biến là nghĩ INC đặt hoặc xóa CF như ADD."}, {"q": "AL = 03h, BL = 05h. Sau <code>SUB AL, BL<\/code>, AL = FEh. Cách đọc cờ nào đúng?", "o": ["CF = 0 vì kết quả có dấu −2 vẫn hợp lệ", "OF = 1 vì kết quả là số âm", "CF = 1 vì không dấu 3 &lt; 5; OF = 0 vì có dấu −2 đúng", "CF = 1 và OF = 1 vì phép trừ phải mượn"], "a": 2, "e": "CF báo mượn trong phép trừ không dấu (3 < 5). OF chỉ bằng 1 khi kết quả có dấu sai; 3 − 5 = −2 nằm trong −128…127 nên OF = 0. Kết quả âm được báo ở SF = 1, không phải OF."}, {"q": "Sau <code>ADD AX, BX<\/code>, AX = 0700h. PF bằng mấy?", "o": ["PF = 0: cả AX có 3 bit 1 (lẻ)", "PF = 0: byte cao 07h có 3 bit 1 (lẻ)", "PF không đổi vì ADD 16 bit không đặt PF", "PF = 1: chỉ xét byte thấp 00h, có 0 bit 1 (chẵn)"], "a": 3, "e": "PF luôn tính trên 8 bit thấp của kết quả, kể cả phép tính 16 bit. Byte thấp 00h có 0 bit 1, số chẵn, nên PF = 1."}, {"q": "Lệnh nào <b>không<\/b> đổi cờ nào?", "o": ["<code>MOV AL, 0<\/code>", "<code>XOR AL, AL<\/code>", "<code>SUB AL, AL<\/code>", "<code>INC AL<\/code>"], "a": 0, "e": "MOV chỉ chép dữ liệu, không đổi cờ. XOR AL, AL và SUB AL, AL cũng cho AL = 0 nhưng đặt ZF = 1, CF = 0; INC đổi mọi cờ trạng thái trừ CF."}]);

